function maximumStrongPairXor(nums) {
  // Try every possible XOR value from the top down and stop at the first one some strong pair produces.
  const present = new Set(nums);
  for (let target = 127; target > 0; target--) {
    for (const x of present) {
      const y = x ^ target;
      if (present.has(y) && Math.max(x, y) <= 2 * Math.min(x, y)) return target;
    }
  }
  return 0;
}

