function generate(rand, size) {
  const pick = (low, high) => low + Math.floor(rand() * (high - low + 1));
  if (size === 'large') {
    const low = rand() < 0.5 ? 1 : pick(1, 60);
    return [Array.from({ length: 50 }, () => pick(low, 100))];
  }
  const n = pick(1, 8);
  const low = pick(1, 100);
  const high = pick(low, Math.min(100, low + pick(0, 60)));
  return [Array.from({ length: n }, () => pick(low, high))];
}
